function soundFX(kind){if(!sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioContext=audioContext||new Audio();const play=()=>{const notes={bounce:[240,480,720],parry:[740,990,1320],stamp:[110,75],boss:[140,210,100],coffee:[590,790,1090],slides:[330,440,550,660],jump:[260,390],shoot:[520,350],point:[660,880],hit:[170,95],win:[392,494,587,784],lose:[294,220,147]}[kind]||[440];const now=audioContext.currentTime;notes.forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=now+i*.075;o.type=kind==='hit'?'triangle':'square';o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.025,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.12);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.13);o.onended=()=>{o.disconnect();g.disconnect();};});};if(audioContext.state==='suspended')audioContext.resume().then(play).catch(()=>{});else play();}catch{}}
